import { useState } from "react";
import { Sparkles, Loader2, Check, Package, RotateCcw, Upload, ChevronLeft } from "lucide-react";

const DARK="#3E3C4F", DARK2="#565469", WHITE="#FFFFFF", CARD="#F7F4F8", LINE="#E7E4EC";
const BLUSH="#E7CCCB", BLUE="#B5D7E6", MUTE="#8E8AA3", SUCCESS="#7FB4C8";
const H = { fontFamily:"'Montserrat',system-ui,sans-serif" };

const LOGO = "data:image/jpeg;base64,";
const ROOM = "data:image/jpeg;base64,";
const MEDIA = "https://materialworldireland.com/media/catalog/product";

// Catalogue built from the live Material World product feed (real image links + prices)
const FABRICS = [
  { id:"marela-apple-green",   name:"Marela Herringbone Apple Green", price:30, group:"green",   pattern:"herring", base:"#8A9A5B", alt:"#6F7C46", img:`${MEDIA}/m/a/marela_herrinngbone_apple_green-3.jpg` },
  { id:"marela-burnt-orange",  name:"Marela Herringbone Burnt Orange",price:30, group:"warm",    pattern:"herring", base:"#B4682F", alt:"#9A5726", img:`${MEDIA}/m/a/marela_herringbone_burnt_orange-4.jpg` },
  { id:"ascot-steel",          name:"Ascot Steel",                    price:26, group:"neutral", pattern:"print",   base:"#C9C3B4", alt:"#AFA790", img:`${MEDIA}/a/s/ascot_steel-3.jpg` },
  { id:"ascot-silver",         name:"Ascot Silver",                   price:26, group:"neutral", pattern:"print",   base:"#BFC2B4", alt:"#A2A794", img:`${MEDIA}/a/s/ascot_silver_-4.jpg` },
  { id:"warwick-cream-grey",   name:"Warwick Cream-Grey Damask",      price:26, group:"neutral", pattern:"print",   base:"#D8D2C4", alt:"#B9B2A2", img:`${MEDIA}/w/a/warwick_cream-grey_damask-2.jpg` },
  { id:"victoria-oyster",      name:"Victoria Oyster",                price:26, group:"neutral", pattern:"print",   base:"#D6C7B0", alt:"#BBA98E", img:`${MEDIA}/v/i/victoria_oyster-3_1.jpg` },
  { id:"victoria-steel",       name:"Victoria Steel",                 price:26, group:"neutral", pattern:"print",   base:"#A6A7A3", alt:"#86877F", img:`${MEDIA}/v/i/victoria_steel-2_1.jpg` },
  { id:"albion-navy-stripe",   name:"Albion Navy Stripe",             price:26, group:"blue",    pattern:"stripe",  base:"#33405A", alt:"#8A8168", img:`${MEDIA}/_/a/_albion_stripe-3.jpg` },
  { id:"agapanthus-blue-large",name:"Agapanthus Blue Large",          price:35, group:"blue",    pattern:"print",   base:"#7C97B4", alt:"#C9D4DE", img:`${MEDIA}/2/1/21-5.jpg` },
  { id:"toile-blue",           name:"Toile Blue",                     price:40, group:"blue",    pattern:"print",   base:"#9FB6C8", alt:"#2E4A63", img:`${MEDIA}/1/-/1-2_18.jpg` },
  { id:"hampton-blossom-blue", name:"Hampton Blossom Pale Blue",      price:28, group:"blue",    pattern:"print",   base:"#B9CBD8", alt:"#6E8CA6", img:`${MEDIA}/b/l/blossom_blue-2.jpg` },
  { id:"toile-green",          name:"Toile Green",                    price:40, group:"green",   pattern:"print",   base:"#8A9A6E", alt:"#3E4E2E", img:`${MEDIA}/1/-/1-2_22.jpg` },
  { id:"chateau-green-floral", name:"Chateau Green Floral",           price:26, group:"green",   pattern:"print",   base:"#6E7A52", alt:"#4E5A38", img:`${MEDIA}/1/-/1-5_22.jpg` },
  { id:"warwick-gold-damask",  name:"Warwick Gold Damask",            price:26, group:"warm",    pattern:"print",   base:"#B79A54", alt:"#977B38", img:`${MEDIA}/w/a/warwick_gold_damask-5.jpg` },
  { id:"vasco",                name:"Vasco Wine & Gold",              price:35, group:"warm",    pattern:"print",   base:"#7A3B44", alt:"#B79A54", img:`${MEDIA}/v/a/vasco-2.jpg` },
  { id:"rustico-gold-floral",  name:"Rustico Gold Floral",            price:35, group:"warm",    pattern:"print",   base:"#8A5B4A", alt:"#B79A54", img:`${MEDIA}/1/-/1-3_43.jpg` },
  { id:"agapanthus-red-large", name:"Agapanthus Red Large",           price:35, group:"warm",    pattern:"print",   base:"#9A4B44", alt:"#C9C4A0", img:`${MEDIA}/1/-/1-2_5.jpg` },
];
const byId = id => FABRICS.find(f=>f.id===id);

const FALLBACK = {
  style:"Warm bedroom nook, deep reveal, natural evening light",
  palette:["#D8C9B6","#2F2620","#9FBEC4","#B5714A","#5E7245"],
  picks:[
    { id:"marela-apple-green",  reason:"Greens echo the snake plants and settle the nook." },
    { id:"marela-burnt-orange", reason:"Warms the cool light and picks up the terracotta pot." },
    { id:"hampton-blossom-blue",reason:"Soft blue nods to the throw and keeps it calm." },
    { id:"ascot-steel",         reason:"A light cream-grey to keep the small window airy." },
  ],
};

function fabricBg(f){
  const b=f.base;
  switch(f.pattern){
    case "herring":return `repeating-linear-gradient(45deg,${b} 0 5px,${f.alt} 5px 10px),repeating-linear-gradient(-45deg,rgba(0,0,0,.05) 0 5px,rgba(255,255,255,.05) 5px 10px)`;
    case "stripe": return `repeating-linear-gradient(90deg,${b} 0 12px,${f.alt} 12px 20px)`;
    case "print":  return `radial-gradient(circle at 24% 28%,${f.alt} 0 3px,transparent 4px),radial-gradient(circle at 68% 62%,${f.alt} 0 3px,transparent 4px),${b}`;
    default:       return `linear-gradient(180deg,rgba(255,255,255,.05),rgba(0,0,0,.06)),${b}`;
  }
}

export default function MWVisualiser(){
  const [step,setStep]=useState("intro");
  const [room,setRoom]=useState(ROOM);
  const [analysis,setAnalysis]=useState(null);
  const [cards,setCards]=useState([]);
  const [selected,setSelected]=useState([]);
  const [note,setNote]=useState("");

  function onFile(e){ const file=e.target.files?.[0]; if(!file) return; const r=new FileReader(); r.onload=()=>setRoom(String(r.result)); r.readAsDataURL(file); e.target.value=""; }

  async function start(){
    setStep("analysing"); setNote(""); setSelected([]);
    let picks, ana;
    try{
      const res=await fetch("/api/analyse",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ room, fabrics:FABRICS.map(f=>({id:f.id,name:f.name})) })});
      const data=await res.json();
      if(!res.ok) throw new Error(data.error||"analyse failed");
      ana={style:data.style,palette:data.palette||[]}; picks=(data.picks||[]).slice(0,4);
      if(!picks.length) throw new Error("no picks");
    }catch(e){
      ana={style:FALLBACK.style,palette:FALLBACK.palette}; picks=FALLBACK.picks;
      setNote("Showing a sample match with real fabrics. Add your Gemini key on Railway for live AI analysis and on-window renders.");
    }
    setAnalysis(ana);
    const init=picks.map(p=>({ id:p.id, reason:p.reason||"", status:"loading", image:null }));
    setCards(init); setStep("results");
    init.forEach(card=>{ const f=byId(card.id); if(!f) return;
      fetch("/api/render",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ room, fabricUrl:f.img, fabricName:f.name, product:"blind" })})
        .then(async r=>{ const d=await r.json(); if(!r.ok) throw new Error(d.error||"render failed"); return d; })
        .then(d=> setCards(cs=>cs.map(c=>c.id===card.id?{...c,status:"done",image:d.image}:c)))
        .catch(()=> setCards(cs=>cs.map(c=>c.id===card.id?{...c,status:"error"}:c)));
    });
  }

  const toggle=id=> setSelected(s=> s.includes(id)? s.filter(x=>x!==id) : [...s,id]);
  const reset=()=>{ setStep("intro"); setRoom(ROOM); setAnalysis(null); setCards([]); setSelected([]); setNote(""); };

  return (
    <div style={{background:WHITE,color:DARK,minHeight:"100%",...H}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;500;600;700&display=swap');*{box-sizing:border-box}`}</style>

      <div style={{background:DARK,color:WHITE,fontSize:11,letterSpacing:1.5,textAlign:"center",padding:"7px",fontWeight:500}}>FREE SHIPPING FOR ORDERS OVER €75 ONLINE</div>
      <div className="flex items-center justify-between" style={{padding:"14px 20px",borderBottom:`1px solid ${LINE}`,background:WHITE}}>
        <img src={LOGO} alt="Material World" style={{height:30}}/>
        <div className="hidden md:flex" style={{gap:24,fontSize:13,color:DARK2,letterSpacing:.3}}>
          <span>Our Fabrics</span><span style={{color:DARK,fontWeight:600,borderBottom:`2px solid ${BLUSH}`,paddingBottom:2}}>Room Visualiser</span><span>Made to Measure</span><span>Outlet</span>
        </div>
        <div style={{fontSize:12,color:MUTE}}>Naas, Co. Kildare</div>
      </div>

      <div className="max-w-5xl mx-auto" style={{padding:"26px 20px 44px"}}>
        {step==="intro" && (
          <div className="flex flex-col md:flex-row" style={{gap:30,alignItems:"center"}}>
            <div style={{flex:"0 0 auto",width:"100%",maxWidth:340,position:"relative"}}>
              <div style={{position:"absolute",inset:"-10px -10px auto auto",width:120,height:120,background:BLUE,borderRadius:"50%",opacity:.4,zIndex:0}}/>
              <img src={room} alt="your room" style={{position:"relative",zIndex:1,width:"100%",borderRadius:12,boxShadow:"0 18px 44px rgba(62,60,79,.20)",display:"block"}}/>
            </div>
            <div style={{flex:1}}>
              <div style={{fontSize:11,letterSpacing:2.5,color:MUTE,textTransform:"uppercase",fontWeight:600}}>Free fabric matching</div>
              <h1 style={{...H,fontSize:40,fontWeight:300,lineHeight:1.05,margin:"8px 0 14px",color:DARK}}>Find the fabric your room is asking for</h1>
              <p style={{fontSize:15,color:DARK2,lineHeight:1.55,marginBottom:22,maxWidth:440}}>We read your window, colours and light, then show four Material World fabrics made up on your own window. Love a few? We will post the swatches to your door, free.</p>
              <div className="flex items-center flex-wrap" style={{gap:16}}>
                <button onClick={start} style={{display:"inline-flex",alignItems:"center",gap:8,background:DARK,color:WHITE,fontWeight:600,fontSize:15,border:"none",borderRadius:40,padding:"13px 26px",cursor:"pointer",...H}}><Sparkles size={17}/> Match my room</button>
                <label style={{display:"inline-flex",alignItems:"center",gap:7,fontSize:13,color:MUTE,cursor:"pointer"}}><Upload size={14}/> Use a different room photo<input type="file" accept="image/*" onChange={onFile} style={{display:"none"}}/></label>
              </div>
            </div>
          </div>
        )}

        {step==="analysing" && (
          <div className="flex flex-col items-center justify-center" style={{gap:18,padding:"64px 0",textAlign:"center"}}>
            <div style={{position:"relative",width:220}}>
              <img src={room} alt="your room" style={{width:"100%",borderRadius:12,filter:"brightness(.7)"}}/>
              <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",color:WHITE}}><Loader2 size={26} className="animate-spin"/></div>
            </div>
            <div style={{...H,fontSize:20,fontWeight:400,color:DARK}}>Reading your room’s light, colour and style…</div>
          </div>
        )}

        {step==="results" && analysis && (
          <div>
            <div className="flex items-center justify-between flex-wrap" style={{gap:12,marginBottom:18}}>
              <div>
                <div style={{fontSize:11,letterSpacing:2,color:MUTE,textTransform:"uppercase",fontWeight:600}}>Your room</div>
                <div style={{...H,fontSize:24,fontWeight:400,color:DARK}}>{analysis.style}</div>
              </div>
              <div className="flex" style={{gap:6}}>{analysis.palette.map((c,i)=><div key={i} title={c} style={{width:26,height:26,borderRadius:6,background:c,border:`1px solid ${LINE}`}}/>)}</div>
            </div>
            {note && <div style={{fontSize:12,color:MUTE,marginBottom:14}}>{note}</div>}

            <div className="grid grid-cols-2" style={{gap:16}}>
              {cards.map(card=>{ const f=byId(card.id); if(!f) return null; const sel=selected.includes(card.id);
                return (
                  <button key={card.id} onClick={()=>toggle(card.id)} style={{textAlign:"left",background:CARD,border:`2px solid ${sel?DARK:LINE}`,borderRadius:14,overflow:"hidden",cursor:"pointer",padding:0}}>
                    <div style={{position:"relative",aspectRatio:"1",background:fabricBg(f)}}>
                      <img src={card.image || f.img} alt={f.name} onError={e=>{e.currentTarget.style.display="none";}} style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}}/>
                      {card.status==="loading" && <div style={{position:"absolute",inset:0,background:"rgba(62,60,79,.45)",display:"flex",alignItems:"center",justifyContent:"center",color:WHITE}}><Loader2 size={22} className="animate-spin"/></div>}
                      {card.status==="error" && <div style={{position:"absolute",bottom:6,left:6,fontSize:10,color:WHITE,background:"rgba(62,60,79,.7)",padding:"2px 6px",borderRadius:8}}>fabric shown flat</div>}
                      {sel && <div style={{position:"absolute",top:8,right:8,width:26,height:26,borderRadius:"50%",background:BLUE,color:DARK,display:"flex",alignItems:"center",justifyContent:"center"}}><Check size={16}/></div>}
                    </div>
                    <div style={{padding:"11px 13px"}}>
                      <div className="flex items-center justify-between"><span style={{fontSize:13,fontWeight:600,color:DARK}}>{f.name}</span><span style={{fontSize:12,color:DARK2}}>€{f.price}/m</span></div>
                      <div style={{fontSize:11.5,color:MUTE,lineHeight:1.35,marginTop:3}}>{card.reason}</div>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="flex items-center justify-between flex-wrap" style={{gap:12,marginTop:22}}>
              <button onClick={reset} style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:13,color:MUTE,background:"transparent",border:"none",cursor:"pointer",...H}}><RotateCcw size={14}/> Start over</button>
              <button disabled={!selected.length} onClick={()=>setStep("order")} style={{display:"inline-flex",alignItems:"center",gap:8,background:selected.length?DARK:LINE,color:selected.length?WHITE:MUTE,fontWeight:600,fontSize:15,border:"none",borderRadius:40,padding:"13px 26px",cursor:selected.length?"pointer":"default",...H}}><Package size={17}/> Order free swatches{selected.length?` (${selected.length})`:""}</button>
            </div>
          </div>
        )}

        {step==="order" && (
          <div className="max-w-md mx-auto">
            <button onClick={()=>setStep("results")} style={{display:"inline-flex",alignItems:"center",gap:5,fontSize:13,color:MUTE,background:"transparent",border:"none",cursor:"pointer",marginBottom:14,...H}}><ChevronLeft size={15}/> Back to fabrics</button>
            <h2 style={{...H,fontSize:27,fontWeight:400,marginBottom:6,color:DARK}}>Order your free swatches</h2>
            <p style={{fontSize:14,color:DARK2,marginBottom:18}}>We will post these samples to your door so you can feel the weight and see the colour in your own light.</p>
            <div style={{background:CARD,border:`1px solid ${LINE}`,borderRadius:12,padding:12,marginBottom:18}}>
              {selected.map(id=>{ const f=byId(id); return (
                <div key={id} className="flex items-center" style={{gap:10,padding:"6px 0"}}><img src={f.img} alt="" onError={e=>{e.currentTarget.style.visibility="hidden";}} style={{width:34,height:34,borderRadius:7,objectFit:"cover",background:fabricBg(f)}}/><span style={{fontSize:13,fontWeight:500,flex:1,color:DARK}}>{f.name}</span><span style={{fontSize:12,color:MUTE}}>€{f.price}/m</span></div>
              );})}
            </div>
            <input placeholder="Name" style={inp}/>
            <input placeholder="Email" style={inp}/>
            <input placeholder="Address" style={inp}/>
            <input placeholder="Eircode" style={inp}/>
            <button onClick={()=>setStep("done")} style={{width:"100%",marginTop:6,background:DARK,color:WHITE,fontWeight:600,fontSize:15,border:"none",borderRadius:40,padding:"14px",cursor:"pointer",...H}}>Send my swatches</button>
          </div>
        )}

        {step==="done" && (
          <div className="max-w-md mx-auto" style={{textAlign:"center",padding:"44px 0"}}>
            <div style={{width:58,height:58,borderRadius:"50%",background:SUCCESS,color:WHITE,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 18px"}}><Check size={28}/></div>
            <h2 style={{...H,fontSize:28,fontWeight:400,marginBottom:8,color:DARK}}>Your swatches are on their way</h2>
            <p style={{fontSize:14,color:DARK2,marginBottom:20}}>{selected.length} sample{selected.length>1?"s":""} posting from our Naas showroom. Keep an eye on your letterbox, and reply any time for a free, no obligation quote.</p>
            <button onClick={reset} style={{display:"inline-flex",alignItems:"center",gap:8,background:"transparent",color:DARK,fontWeight:600,fontSize:14,border:`1px solid ${DARK}`,borderRadius:40,padding:"11px 22px",cursor:"pointer",...H}}><RotateCcw size={15}/> Try another room</button>
          </div>
        )}
      </div>

      <div style={{background:DARK,color:WHITE,fontSize:11.5,textAlign:"center",padding:"16px"}}>Live prototype for Material World, built by Nuadesign.</div>
    </div>
  );
}
const inp={width:"100%",background:WHITE,color:DARK,border:`1px solid ${LINE}`,borderRadius:10,padding:"12px 14px",fontSize:14,marginBottom:10,outline:"none",fontFamily:"'Montserrat',sans-serif"};
